// Sefaria: where a sage's own writings (or, for people who wrote none, the
// sources about them) can be read. public/data-sefaria.json is generated by
// scripts/build_sefaria_links.py from sefaria.org's public API, keyed by sage id.
// Bundled at build time like the other data files, so a sage page makes no
// request to Sefaria until the reader clicks through.
import sefariaData from '../public/data-sefaria.json'

export interface SefariaWork {
  he: string
  en: string
  /** Path on sefaria.org, e.g. "/Rashi_on_Avot" or "/texts/Tanakh/Rishonim on Tanakh/Rashi". */
  url: string
  /** A collection of texts rather than a single book. */
  cat?: boolean
}

export interface SefariaEntry {
  /** The roster label this entry was matched against; guards against ids drifting. */
  label: string
  /** Sefaria topic slug, the key of the author's / person's page. */
  slug: string
  /** "author": Sefaria lists works under this name. "person": it lists only the sources about him. */
  kind: 'author' | 'person'
  he: string
  en: string
  /** Works Sefaria lists for the author, which can be more than `works` holds. */
  total: number
  works: SefariaWork[]
}

const entries = (sefariaData as unknown as { authors: Record<string, SefariaEntry> }).authors

export function getSefaria(sageId: string): SefariaEntry | undefined {
  return entries[sageId]
}

export function sefariaEntryCount(): number {
  return Object.keys(entries).length
}

export function sefariaEntries(): Array<[string, SefariaEntry]> {
  return Object.entries(entries)
}

const ORIGIN = 'https://www.sefaria.org'

/** The author's / person's page: works, and every source that mentions him. */
export function sefariaTopicUrl(slug: string): string {
  return `${ORIGIN}/topics/${encodeURIComponent(slug)}`
}

/** A work (or collection) page, from the path Sefaria returned. */
export function sefariaWorkUrl(path: string): string {
  return ORIGIN + encodeURI(path)
}
